def cell_volume(self, params: np.ndarray) -> float:
    """Cell volume at these parameters, in cubic Angstrom.

    Only the cell block matters: slot displacements move the
    contents of the cell, never the cell itself.
    """
    cell_free, _ = self.split(params)
    return abs(float(np.linalg.det(self.matrix_for(cell_free))))

